class Solution {
    private static final int INF = 1_000_000_000;

    public int mergeStones(int[] stones, int k) {
        int n = stones.length;
        if ((n - 1) % (k - 1) != 0) {
            return -1;
        }

        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }

        int[][][] dp = new int[n][n][k + 1];
        for (int left = 0; left < n; left++) {
            for (int right = 0; right < n; right++) {
                java.util.Arrays.fill(dp[left][right], INF);
            }
            dp[left][left][1] = 0;
        }

        for (int length = 2; length <= n; length++) {
            for (int left = 0; left + length <= n; left++) {
                int right = left + length - 1;
                for (int piles = 2; piles <= k; piles++) {
                    for (int split = left; split < right; split++) {
                        if (dp[left][split][1] == INF || dp[split + 1][right][piles - 1] == INF) {
                            continue;
                        }
                        dp[left][right][piles] = Math.min(
                                dp[left][right][piles],
                                dp[left][split][1] + dp[split + 1][right][piles - 1]);
                    }
                }
                if (dp[left][right][k] != INF) {
                    dp[left][right][1] = dp[left][right][k] + prefix[right + 1] - prefix[left];
                }
            }
        }
        return dp[0][n - 1][1];
    }
}

class Solution {
    private static final int INF = 1_000_000_000;
    private int k;
    private int[] prefix;
    private int[][][] memo;

    public int mergeStones(int[] stones, int k) {
        int n = stones.length;
        if ((n - 1) % (k - 1) != 0) {
            return -1;
        }
        this.k = k;
        prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }

        memo = new int[n][n][k + 1];
        for (int left = 0; left < n; left++) {
            for (int right = 0; right < n; right++) {
                java.util.Arrays.fill(memo[left][right], -1);
            }
        }
        return cost(0, n - 1, 1);
    }

    private int cost(int left, int right, int piles) {
        int length = right - left + 1;
        if (length < piles || (length - piles) % (k - 1) != 0) {
            return INF;
        }
        if (left == right) {
            return piles == 1 ? 0 : INF;
        }
        if (memo[left][right][piles] != -1) {
            return memo[left][right][piles];
        }

        if (piles == 1) {
            int beforeFinalMerge = cost(left, right, k);
            memo[left][right][piles] = beforeFinalMerge + prefix[right + 1] - prefix[left];
            return memo[left][right][piles];
        }

        int best = INF;
        for (int split = left; split < right; split++) {
            int first = cost(left, split, 1);
            int rest = cost(split + 1, right, piles - 1);
            if (first == INF || rest == INF) {
                continue;
            }
            best = Math.min(best, first + rest);
        }
        memo[left][right][piles] = best;
        return best;
    }
}

class Solution {
    private static final int INF = 1_000_000_000;
    private int k;
    private int[] prefix;
    private int[][] memo;

    public int mergeStones(int[] stones, int k) {
        int n = stones.length;
        if ((n - 1) % (k - 1) != 0) {
            return -1;
        }
        this.k = k;
        prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }

        memo = new int[n][n];
        for (int[] row : memo) {
            java.util.Arrays.fill(row, -1);
        }
        return solve(0, n - 1);
    }

    private int solve(int left, int right) {
        if (left == right) {
            return 0;
        }
        if (memo[left][right] != -1) {
            return memo[left][right];
        }

        int best = INF;
        for (int split = left; split < right; split += k - 1) {
            best = Math.min(best, solve(left, split) + solve(split + 1, right));
        }
        if ((right - left) % (k - 1) == 0) {
            best += prefix[right + 1] - prefix[left];
        }
        memo[left][right] = best;
        return best;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int mergeStones(int[] stones, int k) {
        int n = stones.length;
        if ((n - 1) % (k - 1) != 0) {
            return -1;
        }

        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }

        @SuppressWarnings("unchecked")
        Map<Integer, Integer>[][] dp = new HashMap[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = new HashMap<>();
            dp[i][i].put(1, 0);
        }

        for (int length = 2; length <= n; length++) {
            for (int left = 0; left + length <= n; left++) {
                int right = left + length - 1;
                Map<Integer, Integer> current = new HashMap<>();
                for (int split = left; split < right; split++) {
                    Map<Integer, Integer> first = dp[left][split];
                    Map<Integer, Integer> second = dp[split + 1][right];
                    for (Map.Entry<Integer, Integer> a : first.entrySet()) {
                        for (Map.Entry<Integer, Integer> b : second.entrySet()) {
                            int piles = a.getKey() + b.getKey();
                            if (piles > k) {
                                continue;
                            }
                            int cost = a.getValue() + b.getValue();
                            current.merge(piles, cost, Math::min);
                        }
                    }
                }

                Integer kPileCost = current.get(k);
                if (kPileCost != null) {
                    current.merge(1, kPileCost + prefix[right + 1] - prefix[left], Math::min);
                }
                dp[left][right] = current;
            }
        }
        return dp[0][n - 1].get(1);
    }
}
